export interface ConfigField {
    key: string;
    label: string;
    type: FieldType;
    description: string;
    default?: unknown;
    choices?: string[];
    required?: boolean;
    channelTypes?: ChannelType[];
    claimable?: boolean;
    step?: number;
    min?: number;
    max?: number;
    quickPicks?: string[];
    group?: string;
    section?: string;
    subfields?: ConfigField[];
    format?: string;
    templateVars?: string[];
    richPreview?: {
        accentColorKey?: string;
        footerKey?: string;
        imageUrlsKey?: string;
        buttonsKey?: string;
        thumbnailKey?: string;
    };
    pairedWith?: string;
    enabledBy?: string;
    widget?: ConfigWidget;
}

abstract class Module {
  meta: ModuleMeta | undefined;
}

export type ModuleMeta = ModuleOptions & {
    displayName: string;
    configFields: ConfigField[];
};

export type ModuleOptions = Omit<ModuleDefinition, "configOverrides" | "dashboardHref"> & {
    name: string;
};

abstract class BaseCommand {
  readonly name: string;
  readonly description: string;
  readonly options: CommandOptions;
  constructor(options: CommandOptions): BaseCommand;
  registerApplicationCommands(registry: CommandRegistry): void;
  abstract run(ctx: CommandContext): unknown | Promise<unknown>;
}

abstract class BaseSubcommand {
  constructor(options: SubcommandOptions): BaseSubcommand;
  readonly subcommands: SubcommandRoute[];
  run(ctx: CommandContext): unknown | Promise<unknown>;
}

class CommandContext {
  readonly isSlash: boolean;
  readonly guildId: string | null;
  readonly channelId: string;
  readonly user: SerialisedUser;
  readonly member: SerialisedMember | null;
  readonly subcommand: string | null;
  constructor(invocation: AddonCommandInvocation): CommandContext;
  getString(name: string, spec?: CtxOptionSpec): Promise<string | null>;
  getInteger(name: string, spec?: CtxOptionSpec): Promise<number | null>;
  getNumber(name: string, spec?: CtxOptionSpec): Promise<number | null>;
  getBoolean(name: string, spec?: CtxOptionSpec): Promise<boolean | null>;
  defer(opts?: CtxReplyOptions): Promise<void>;
  reply(card: CardReply, opts?: CtxReplyOptions): Promise<void>;
  replySuccess(title: string, body: string, opts?: CtxReplyOptions): Promise<void>;
  replyError(title: string, body: string, opts?: CtxReplyOptions): Promise<void>;
  replyWarning(title: string, body: string, opts?: CtxReplyOptions): Promise<void>;
  replyInfo(title: string, body: string, opts?: CtxReplyOptions): Promise<void>;
  replyEmpty(title: string, reason: string, suggestion?: string, opts?: CtxReplyOptions): Promise<void>;
  checkPermit(node: string): Promise<void>;
}

export interface CommandOptions {
    name: string;
    description: string;
    requiredPermit?: string;
    cooldownDelay?: number;
    prefixEnabled?: boolean;
}

export interface CommandRegistry {
    registerChatInputCommand(build: (builder: SlashCommandBuilder) => {
        toJSON(): unknown;
    }): void;
}

export interface CtxOptionSpec {
    required?: boolean;
    rest?: boolean;
}

export interface CtxReplyOptions {
    ephemeral?: boolean;
}

export interface SubcommandOptions extends CommandOptions {
    subcommands: SubcommandRoute[];
}

export interface SubcommandRoute {
    name: string;
    run: string;
}

export type MessagePayload = CardReply | {
    content?: string;
    components?: unknown[];
};

export interface SentMessage {
    id: string;
    channelId: string;
}

abstract class BaseInteractionHandler {
  readonly prefix: string;
  abstract run(ctx: InteractionContext): unknown | Promise<unknown>;
}

class InteractionContext {
  readonly customId: string;
  readonly guildId: string | null;
  readonly channelId: string;
  readonly user: SerialisedUser;
  readonly member: SerialisedMember | null;
  readonly values: string[];
  readonly fields: Record<string, string>;
  constructor(invocation: AddonInteractionInvocation): InteractionContext;
  reply(card: CardReply, opts?: { ephemeral?: boolean; }): Promise<void>;
  replySuccess(title: string, body: string): Promise<void>;
  replyError(title: string, body: string): Promise<void>;
  replyWarning(title: string, body: string): Promise<void>;
  replyInfo(title: string, body: string): Promise<void>;
  defer(opts?: { ephemeral?: boolean; }): Promise<void>;
  showModal(modal: { toJSON(): unknown; }): Promise<void>;
}

export interface AccessoryButton {
    customId: string;
    label?: string;
    style?: ButtonStyle;
    emoji?: string | APIMessageComponentEmoji;
    disabled?: boolean;
}

export interface CardOptions {
    subtitle?: string;
    breadcrumbs?: string[];
    statusBadge?: {
        status: string;
        label?: string;
    };
    footer?: string;
    thumbnail?: string;
    thumbnailUrl?: string;
    divider?: boolean;
    sections?: SectionBuilder[];
    actionRows?: ActionRowBuilder<MessageActionRowComponentBuilder | any>[];
    separatorAboveActionRows?: boolean;
    mediaGallery?: MediaGalleryBuilder;
    headerImages?: string[];
}

export interface CardReply {
    readonly flags?: number;
    readonly components: readonly ContainerBuilder[];
    readonly allowedMentions?: MessageMentionOptions;
}

export interface ConfirmPromptOptions {
    title: string;
    body: string;
    confirmLabel?: string;
    cancelLabel?: string;
    time?: number;
    channel?: GuildTextBasedChannel;
}

export interface ConfirmRowOptions {
    confirmId: string;
    cancelId: string;
    confirmLabel?: string;
    cancelLabel?: string;
    confirmStyle?: ButtonStyle;
}

export interface NavAction {
    customId: string;
    label: string;
    style?: ButtonStyle;
    emoji?: string | APIMessageComponentEmoji;
    disabled?: boolean;
}

export interface NavRowOptions {
    backId: string;
    backLabel?: string;
    action: NavAction;
}

export interface Tab {
    id: string;
    label: string;
    emoji?: string;
}
